insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('abstract-reasoning-pro', 'Abstract Reasoning Pro', 'Advanced non-verbal matrix reasoning beyond Spatial Intelligence — denser rule sets, higher ceiling.', 'Abstract Reasoning Pro is built on the Raven''s Progressive Matrices paradigm (Raven, 1936) — the archetypal non-verbal matrix-reasoning test, still one of the most widely used non-verbal intelligence measures today. Each item shows a 3x3 grid following a rule across shape, color, rotation, and/or count' || chr(59) || ' you identify the rule and pick the option that completes the missing cell. This version runs denser than Spatial Intelligence''s matrix section — most items combine two or three simultaneously-changing attributes rather than one.', 'box', (select id from assessment_categories where key = 'logical'), ('pattern_recognition')::assessment_engine_type, ('hard')::assessment_difficulty, 20, 20, false, ('premium')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'abstract-reasoning', 'Abstract Reasoning', 'Non-verbal pattern reasoning across simultaneously-varying attributes.', true, 'logical', 1)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'overall', 0, 30, 'Developing', 'Spotting a single rule is manageable, but grids with two or three attributes changing at once are difficult to fully untangle right now.', ARRAY['Work through one attribute at a time — check shape first, then color, then rotation, rather than all at once', 'Practice on Spatial Intelligence''s single-attribute matrices before returning here', 'For each row and column, name out loud what stays the same and what changes']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'overall', 31, 50, 'Average', 'Two-attribute grids are usually solvable, but three-attribute or distribution-of-three items are still error-prone.', ARRAY['When a grid feels ambiguous, check whether the rule might be a row/column pattern rather than a simple repeat', 'Practice specifically on items where every row (or column) contains the same three values in different positions']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'overall', 51, 70, 'Strong', 'Reliable across most rule types, including grids with two or three simultaneously-changing attributes.', ARRAY['Push into distribution-of-three items specifically — they require checking rows AND columns, not just one', 'Time yourself to build speed once accuracy feels solid']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'overall', 71, 85, 'Very Strong', 'Consistently identifies the governing rule quickly, even across dense, multi-attribute grids.', ARRAY['This level of abstract pattern reasoning transfers directly to Fluid Intelligence Peak''s even more novel rule types', 'Notice which specific rule family (row/column constant, progression, distribution) you solve fastest']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'overall', 86, 100, 'Exceptional', 'Near-perfect performance across every rule type and density level tested.', ARRAY['Try Fluid Intelligence Peak for even more novel, less familiar rule structures', 'This is a strong general-reasoning signal independent of specific knowledge or vocabulary']::text[], NULL, 5);
insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values ((select id from assessments where slug = 'abstract-reasoning-pro'), 'abstract-reasoning', 'logical', 0.5);
